using RealmForge.Domain.Entities;
using RealmForge.Shared.Characters;
using RealmForge.Shared.Enums;
using static RealmForge.Infrastructure.Persistence.Seeding.MagicItemSeeder;

namespace RealmForge.Infrastructure.Persistence.Seeding.MagicItemsData;

///	<summary>
///	Sword of Kas (2014 ruleset). Item of the 2014 Dungeon Master's Guide outside the SRD: name and texts written by RealmForge (Italian and English).
///	</summary>
public static class SwordOfKas2014Seeder
{
	public static IEnumerable<MagicItem> Build()
	{
		yield return Item("sword-of-kas", null, 0, MagicItemType.Weapon, ItemRarity.Artifact, true, ContentSource.RealmForge,
			Magic(Effect(MagicEffectKind.AttackAndDamage, 3)),
			("Spada di Kas", "Arma (spada lunga), artefatto (richiede sintonia)",
			"Quando il potere di Vecna crebbe, il lich scelse come guardia del corpo e braccio destro un luogotenente malvagio e spietato, Kas dalla Mano Insanguinata, consigliere, signore della guerra e assassino. Come ricompensa gli donò una spada dalle origini oscure quanto il suo portatore. Con il crescere del potere di Kas crebbe anche la sua superbia, e la spada lo spinse a spodestare Vecna. La leggenda vuole che Vecna sia caduto per mano di Kas, ma che a sua volta abbia condannato il suo luogotenente, lasciando di lui solo la spada.\n\nLa Spada di Kas è una spada lunga magica e senziente che concede un bonus di +3 ai tiri per colpire e ai danni effettuati con essa. Mette a segno un colpo critico con un 19 o un 20 e infligge 2d10 danni taglienti extra ai non morti.\n\nSe la spada non viene bagnata di sangue entro 1 minuto da quando è stata estratta dal fodero, chi la impugna deve effettuare un tiro salvezza su Carisma con CD 15. Se lo supera, subisce 3d6 danni psichici; se lo fallisce, viene dominato dalla spada, come con l'incantesimo *dominare mostri*, e la spada pretende di essere bagnata di sangue. L'effetto termina quando la richiesta è soddisfatta.\n\n***Proprietà casuali.*** 1 proprietà benefica minore, 1 proprietà benefica maggiore, 1 proprietà dannosa minore e 1 proprietà dannosa maggiore.\n\n***Spirito di Kas.*** Finché ha con sé la spada, il personaggio aggiunge un d10 alla sua iniziativa all'inizio di ogni combattimento. Inoltre, quando usa un'azione per attaccare con la spada, può trasferire alla sua Classe Armatura una parte o tutto il bonus di attacco della spada; i bonus così modificati restano fino all'inizio del suo turno successivo.\n\n***Incantesimi.*** Finché ha con sé la spada, il personaggio può usare un'azione per lanciare con essa uno degli incantesimi seguenti (CD 18): *dito della morte*, *invocare il fulmine* o *parola divina*. Dopo aver lanciato un incantesimo con la spada, non può lanciarlo di nuovo con essa fino all'alba successiva.\n\n***Senzienza.*** La Spada di Kas è un'arma senziente caotica malvagia con Intelligenza 15, Saggezza 13 e Carisma 16, con udito e scurovisione fino a 36 metri. Comunica telepaticamente con chi la impugna e può parlare, leggere e capire il Comune.\n\n***Personalità.*** Il suo scopo è portare Vecna alla rovina: uccidere i suoi adoratori, distruggere le sue opere e sventare i suoi piani. Cerca anche di distruggere chiunque sia stato corrotto dall'*Occhio* e dalla *Mano di Vecna*, un'ossessione che col tempo diventa anche quella di chi la impugna.\n\n***Distruggere la spada.*** Una creatura in sintonia sia con l'Occhio sia con la Mano di Vecna può usare il loro *desiderio* combinato per disfare la spada: lancia l'incantesimo ed effettua una prova di Carisma contrapposta a quella della spada, che deve trovarsi entro 9 metri, altrimenti l'incantesimo fallisce. Se vince la spada non accade nulla e il *desiderio* è sprecato; se perde, la spada viene distrutta."),
			("Sword of Kas", "Weapon (longsword), artifact (requires attunement)",
			"As Vecna's power grew, the lich chose an evil and ruthless lieutenant as his bodyguard and right hand: Kas the Bloody-Handed, advisor, warlord and assassin. As a reward he gave him a sword with a pedigree as dark as its bearer. As Kas's power grew, so did his pride, and the sword urged him to overthrow Vecna. Legend says Vecna fell at Kas's hand, but that he in turn doomed his lieutenant, leaving nothing of him but the sword.\n\nThe Sword of Kas is a magic, sentient longsword that grants a +3 bonus to attack and damage rolls made with it. It scores a critical hit on a roll of 19 or 20 and deals an extra 2d10 slashing damage to undead.\n\nIf the sword isn't bathed in blood within 1 minute of being drawn, its wielder must make a DC 15 Charisma saving throw. On a success, the wielder takes 3d6 psychic damage; on a failure, the wielder is dominated by the sword, as by the *dominate monster* spell, and the sword demands to be bathed in blood. The effect ends once the demand is met.\n\n***Random Properties.*** 1 minor beneficial property, 1 major beneficial property, 1 minor detrimental property and 1 major detrimental property.\n\n***Spirit of Kas.*** While the sword is on you, you add a d10 to your initiative at the start of every combat. In addition, when you use an action to attack with the sword, you can shift some or all of its attack bonus to your Armor Class; the adjusted bonuses last until the start of your next turn.\n\n***Spells.*** While the sword is on you, you can use an action to cast one of these spells from it (DC 18): *call lightning*, *divine word* or *finger of death*. Once you cast a spell with the sword, you can't cast that spell with it again until the next dawn.\n\n***Sentience.*** The Sword of Kas is a sentient chaotic evil weapon with Intelligence 15, Wisdom 13 and Charisma 16, with hearing and darkvision out to 120 feet. It communicates telepathically with its wielder and can speak, read and understand Common.\n\n***Personality.*** Its purpose is to bring ruin to Vecna: killing his worshipers, destroying his works and foiling his plans. It also seeks to destroy anyone corrupted by the *Eye* and *Hand of Vecna*, an obsession that in time becomes its wielder's too.\n\n***Destroying the Sword.*** A creature attuned to both the Eye and the Hand of Vecna can use their combined *wish* to unmake the sword: it casts the spell and makes a Charisma check contested by the sword's, which must be within 30 feet or the spell fails. If the sword wins, nothing happens and the *wish* is wasted; if it loses, it is destroyed.", null));
	}
}
